const { PrismaClient } = require("C:/Users/edmem/kodely-prod/node_modules/@prisma/client");
const fs = require("fs");
const env = fs.readFileSync("C:/Users/edmem/kodely-prod/.env", "utf8");
for (const line of env.split(/\r?\n/)) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
  if (m) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
const db = new PrismaClient();

(async () => {
  const out = {};
  out.users = await db.user.count();
  out.projects = await db.project.count();
  out.builds = await db.build.count();
  out.events = await db.event.count();
  out.eventsByName = await db.event.groupBy({ by: ["name"], _count: { _all: true } });
  out.ledgerCount = await db.creditLedger.count();
  const ledger = await db.creditLedger.findMany({ select: { userId: true, delta: true, reason: true, createdAt: true, balanceAfter: true }, orderBy: { createdAt: "asc" } });
  out.reasonBuckets = {};
  for (const r of ledger) {
    const key = r.reason.startsWith("stripe:") ? "stripe:*" : r.reason.startsWith("reward:") ? "reward:*" : r.reason;
    out.reasonBuckets[key] = out.reasonBuckets[key] || { n: 0, sum: 0, deltas: {} };
    out.reasonBuckets[key].n++;
    out.reasonBuckets[key].sum += r.delta;
    out.reasonBuckets[key].deltas[r.delta] = (out.reasonBuckets[key].deltas[r.delta] || 0) + 1;
  }
  // outstanding balance = latest balanceAfter per user
  const latest = await db.$queryRawUnsafe(`SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter" FROM "CreditLedger" l ORDER BY l."userId", l."createdAt" DESC, l."id" DESC`);
  out.outstanding = latest.reduce((a, r) => a + r.balanceAfter, 0);
  out.usersWithLedger = latest.length;
  out.buildAgg = await db.build.aggregate({ _sum: { costMicros: true, creditsCharged: true } });
  out.buildModels = await db.build.groupBy({ by: ["model"], _count: { _all: true }, _sum: { costMicros: true, creditsCharged: true } });
  out.signupWeeks = await db.$queryRawUnsafe(`SELECT date_trunc('week', "createdAt") AS wk, COUNT(*)::int AS n FROM "User" GROUP BY 1 ORDER BY 1`);
  out.projPublished = await db.project.count({ where: { publishedAt: { not: null } } });
  console.log(JSON.stringify(out, (k, v) => (typeof v === "bigint" ? Number(v) : v), 2));
  await db.$disconnect();
})().catch((e) => { console.error(e); process.exit(1); });

