(async () => {
  console.log("== revenue weekly ==");
  console.log(J(await db.$queryRawUnsafe(`
    SELECT date_trunc('week', l."createdAt") AS week, l."delta"::int AS credits, COUNT(*)::int AS n
    FROM "CreditLedger" l WHERE l."reason" LIKE 'stripe:%' AND l."delta" > 0
    GROUP BY 1, 2 ORDER BY 1, 2`)));

  console.log("== build weekly ==");
  console.log(J(await db.$queryRawUnsafe(`
    SELECT date_trunc('week', b."createdAt") AS week,
           COUNT(*)::int AS builds,
           COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS succeeded,
           COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS failed,
           COALESCE(SUM(b."costMicros"), 0)::bigint AS "costMicros",
           COALESCE(SUM(b."costMicros") FILTER (WHERE b."status" <> 'SUCCEEDED'), 0)::bigint AS "unbilledCostMicros",
           COALESCE(SUM(b."creditsCharged"), 0)::bigint AS "creditsCharged"
    FROM "Build" b GROUP BY 1 ORDER BY 1`)));

  console.log("== liability ==");
  console.log(J(await db.$queryRawUnsafe(`
    WITH per_user AS (
      SELECT "userId",
        COALESCE(SUM("delta") FILTER (WHERE "delta" > 0 AND "reason" LIKE 'stripe:%'), 0) AS purchased,
        COALESCE(SUM("delta") FILTER (WHERE "delta" > 0 AND "reason" NOT LIKE 'stripe:%'), 0) AS granted,
        COALESCE(-SUM("delta") FILTER (WHERE "delta" < 0), 0) AS spent
      FROM "CreditLedger" GROUP BY "userId")
    SELECT COUNT(*)::int AS "usersWithLedger",
