  console.log("== authoritative balance ==");
  console.log(J(await db.$queryRawUnsafe(`
    SELECT COALESCE(SUM(b."balanceAfter"), 0)::bigint AS outstanding, COUNT(*)::int AS n FROM (
      SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter"
      FROM "CreditLedger" l ORDER BY l."userId", l."createdAt" DESC, l."id" DESC) b`)));

  console.log("== cohorts ==");
  console.log(J(await db.$queryRawUnsafe(`
    WITH u AS (SELECT id, date_trunc('week', "createdAt") AS wk FROM "User"),
    fpj AS (SELECT "userId", MIN("createdAt") AS t FROM "Project" GROUP BY 1),
    fb AS (SELECT p."userId" AS uid, MIN(b."createdAt") AS t FROM "Build" b JOIN "Project" p ON p."id" = b."projectId" WHERE b."status" = 'SUCCEEDED' GROUP BY 1),
    fp AS (SELECT "userId", MIN("publishedAt") AS t FROM "Project" WHERE "publishedAt" IS NOT NULL GROUP BY 1),
    pu AS (SELECT "userId", MIN("createdAt") AS t FROM "CreditLedger" WHERE "reason" LIKE 'stripe:%' AND "delta" > 0 GROUP BY 1)
    SELECT u.wk AS week, COUNT(*)::int AS users,
           COUNT(fpj.t)::int AS "createdProject", COUNT(fb.t)::int AS "builtOk",
           COUNT(fp.t)::int AS published, COUNT(pu.t)::int AS purchased
    FROM u LEFT JOIN fpj ON fpj."userId" = u.id LEFT JOIN fb ON fb.uid = u.id
           LEFT JOIN fp ON fp."userId" = u.id LEFT JOIN pu ON pu."userId" = u.id
    GROUP BY 1 ORDER BY 1`)));

  console.log("== retention grid ==");
  console.log(J(await db.$queryRawUnsafe(`
    WITH u AS (SELECT id, date_trunc('week', "createdAt") AS wk FROM "User"),
    act AS (SELECT DISTINCT p."userId" AS uid, date_trunc('week', b."createdAt") AS awk
            FROM "Build" b JOIN "Project" p ON p."id" = b."projectId")
    SELECT u.wk AS cohort,
           (EXTRACT(EPOCH FROM (act.awk - u.wk)) / 604800)::int AS "weekOffset",
           COUNT(DISTINCT u.id)::int AS users
    FROM u JOIN act ON act.uid = u.id
    WHERE act.awk >= u.wk
    GROUP BY 1, 2 ORDER BY 1, 2`)));

  console.log("== events ==");
  console.log(J(await db.$queryRawUnsafe(`
    SELECT "name", COUNT(*)::int AS n, MIN("createdAt") AS first, MAX("createdAt") AS last
    FROM "Event" GROUP BY 1 ORDER BY 2 DESC`)));

  await db.$disconnect();
})().catch((e) => { console.error(e); process.exit(1); });

